from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]
MAN=json.loads((ROOT/'release-manifest-v0.62.0.json').read_text())
REG=json.loads((ROOT/'registry/workspace-product-record-v0.62.0.json').read_text())
MAIN=(ROOT/'wordpress/sustainable-catalyst-workspace/sustainable-catalyst-workspace.php').read_text()
PHP=(ROOT/'wordpress/sustainable-catalyst-workspace/includes/class-sc-workspace.php').read_text()
REGPHP=(ROOT/'wordpress/sustainable-catalyst-workspace/includes/class-sc-workspace-registry.php').read_text()
APP=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/workspace-v0.62.0.js').read_text()
CSS=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/css/workspace-v0.62.0.css').read_text()
HELP=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/sc-workspace-persistence-integrity-v1.js').read_text()
UI=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/sc-workspace-persistence-integrity-ui-v1.js').read_text()
def check(ok,label):
    if not ok: raise SystemExit('FAIL - '+label)
check('Version: 0.62.0' in MAIN,'plugin version')
check((MAN['version'],MAN['previous_version'],MAN['release_name'])==('0.62.0','0.61.0','Product Hardening II: Persistence, Corruption & Recovery Integrity'),'release lineage')
check(MAN['storage_schema_version']==35 and MAN['project_schema']=='sc-workspace-project/20.0' and MAN['schema_migration_required'] is False,'schema stable')
check('/wp-json/sc-workspace/v1/persistence-integrity-contract' in MAN['rest_routes'],'REST manifest')
check("'/persistence-integrity-contract'" in PHP and 'persistence_integrity_contract' in PHP,'REST implementation')
check('data-scw-workspace-view="integrity"' in PHP and 'data-scw-persistence-integrity' in PHP,'Persistence Integrity UI')
check("METADATA_KEY='sc_workspace_persistence_integrity_v0620'" in HELP and "TRANSACTION_KEY='sc_workspace_persistence_txn_v0620'" in HELP,'integrity stores')
check('read-after-write verification failed' in APP and 'integrity.stage' in APP and 'if (!staged?.ok)' in APP and 'integrity.commit' in APP and 'integrity.fail' in APP,'transactional save integration')
check('last-known-good local snapshot in memory' in APP and 'integrity-drift' in APP and 'integrity.lastGoodState' in APP,'recovery behavior')
check("ALGORITHM='fnv1a32'" in HELP and "integrityPurpose:'corruption-detection-not-security'" in HELP,'checksum non-claim')
check('automaticRepair:false' in HELP and 'automaticRestore:false' in HELP and 'canonicalMutation:false' in HELP,'governance boundaries')
check('containsCanonicalWorkspaceContent:true' in HELP and 'automaticUpload:false' in HELP,'explicit recovery exports')
check('projectContentIncluded:false' in HELP and 'rawStateIncluded:false' in HELP,'privacy-minimized diagnostic')
check("BACKUP_KEY = 'sc_workspace_registry_backup_v0620'" in REGPHP and 'LEGACY_PENDING_KEY_V0610' in REGPHP,'registry recovery')
check(REG['public_version']=='0.62.0' and REG['previous_version']=='0.61.0','registry record')
check('workspace-v0.62.0.js' in PHP and 'workspace-v0.62.0.css' in PHP and len(APP)>100000,'current assets')
check('.scw-persistence-integrity{border-top:4px solid #000' in CSS,'4px editorial integrity surface')
for n in ['sc-workspace-persistence-integrity-v1.schema.json','sc-workspace-persistence-transaction-v1.schema.json','sc-workspace-persistence-integrity-report-v1.schema.json','sc-workspace-recovery-candidate-v1.schema.json']:
    json.loads((ROOT/'schemas'/n).read_text())
check((ROOT/'history/release-manifest-v0.61.0.json').exists() and (ROOT/'history/workspace-product-record-v0.61.0.json').exists(),'predecessor history')
check(PHP.count('A free project environment for carrying questions, evidence, data, analysis, decisions, and authored work across Sustainable Catalyst.')==1,'duplicate hero deck remains removed')
print('PASS - v0.62.0 release validator')
